package io.knowledgebrain.learning;
import java.time.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import io.knowledgebrain.contracts.learning.conceptevidence.v1.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class ConceptEvidenceKafkaIntegrationTest {
 @Test void cdcCarriesExactEvidencePinsFullRevisionsTraceAndStableEventIds()throws Exception{
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var clock=Clock.systemUTC();var ids=new UuidV7(clock);UUID space=ids.next(),actor=ids.next(),note=ids.next();String trace="e".repeat(32);var roadmaps=new RoadmapStore(ds,clock);var store=new ConceptEvidenceStore(ds,clock,roadmaps);var r=roadmaps.create(space,actor,"Evidence stream","",trace);r=roadmaps.graph(space,r.roadmapId(),actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","Pinned node","")),List.of()),trace);var roadmap=r.roadmapId();var node=r.nodes().getFirst().nodeId();String key=UUID.randomUUID().toString().replace("-","");var input=new ConceptEvidenceStore.Input(node,space,note,7,"Raw evidence memo");var ref=new ConceptReferenceClient.Reference(space,note,space,actor,7,"Pinned concept","PRIVATE");var e=store.record(space,roadmap,actor,key,input,trace,()->ref).evidence();assertFalse(store.record(space,roadmap,actor,key,input,trace,()->{fail();return null;}).created());store.change(space,roadmap,e.evidenceId(),actor,1,"Corrected evidence",false,trace);store.change(space,roadmap,e.evidenceId(),actor,2,null,true,trace);
  var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),e.evidenceId()).forEach(v->expected.put(v.getKey(),v.getValue()));assertEquals(3,expected.size());var p=new LearningStudyKafkaIntegrationTest().options();p.put("group.id","learning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer",StringDeserializer.class.getName());p.put("value.deserializer",ByteArrayDeserializer.class.getName());
  try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("learning.concept-evidence.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long end=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<3&&System.nanoTime()<end)for(var record:c.poll(Duration.ofSeconds(1))){if(!record.key().equals(e.evidenceId().toString()))continue;var envelope=ConceptEvidenceEventEnvelopeV1.parseFrom(record.value());var payload=ConceptEvidenceChangedPayloadV1.parseFrom(envelope.getPayload());assertArrayEquals(expected.get(envelope.getEventId()),record.value());assertEquals(actor.toString(),envelope.getActorId());assertEquals(space.toString(),envelope.getSpaceId());assertEquals(trace,envelope.getTraceId());assertEquals("ConceptLearningEvidence",envelope.getAggregateType());assertEquals("learning-service",envelope.getProducer());assertEquals(e.evidenceId().toString(),payload.getEvidenceId());assertEquals(roadmap.toString(),payload.getRoadmapId());assertEquals(node.toString(),payload.getNodeId());assertEquals(note.toString(),payload.getConceptId());assertEquals(7,payload.getConceptVersion());assertEquals(space.toString(),payload.getConceptSpaceId());assertEquals("PRIVATE",payload.getConceptVisibility());assertEquals("Pinned concept",payload.getConceptTitle());assertEquals("Pinned node",payload.getNodeTitle());assertEquals("PRIVATE",payload.getVisibility());assertEquals(payload.getVersion()==1?"Raw evidence memo":"Corrected evidence",payload.getMemo());assertEquals(payload.getVersion()==3?"RETIRED":"ACTIVE",payload.getState());assertEquals(7,UUID.fromString(envelope.getEventId()).version());assertEquals(7,UUID.fromString(payload.getRevisionId()).version());for(var h:Map.of("trace_id",trace,"schema_group","learning","schema_artifact","concept-evidence-events","schema_version","1").entrySet()){var header=record.headers().lastHeader(h.getKey());assertNotNull(header);assertEquals(h.getValue(),new String(header.value(),StandardCharsets.UTF_8));}if(found.add(envelope.getEventId()))versions.add(payload.getVersion());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L),versions);}
 }
}
